from pathlib import Path
import json,hashlib,gzip,base64,datetime
r=Path('/tmp/engine-after-hypot2-20261104');h=Path('/tmp/engine-history-duplicates-20261104');repo=Path('/home/holo/line')
def file(p):
 b=p.read_bytes();return {'sha256':hashlib.sha256(b).hexdigest(),'text':b.decode()}
def blob(p):
 b=p.read_bytes();return {'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'gzipBase64':base64.b64encode(gzip.compress(b,mtime=0)).decode()}
files={p.name:file(p) for p in sorted(r.iterdir()) if p.is_file() and p.suffix in {'.json','.log','.mts','.py'}}
for name in ['instrumented-parity.ts','protocol.json','result.json']:files['profile/'+name]=file(r/'profile'/name)
for p in sorted(h.iterdir()):
 if p.is_file() and p.suffix in {'.txt','.json','.log','.mts','.rs'} and p.name!='track.json':files['history/'+p.name]=file(p)
for name in ['src/kernel.rs','src/abi.rs','manifest.json','manifest.json.sha256']:files['history/shadow/'+name]=file(h/'shadow/scripts/lib/native_motion'/name)
counts=json.loads((h/'counts.json').read_text());assert counts['status']=='PASS'
result={'schema':'line.engine-after-hypot2-diagnostics.v1','updatedUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
 'status':'Diagnostics only; no implementation change',
 'reference':{'productionCommit':'144ae46c','sourceSha256':'2041409c97bd0c0c56f703247853f85978f63e9664ad84b11a6673da177184f4','nativeSha256':'36c2fc92bc5a4e0c4655819b278592a8107a7bbd347afc54c68206307e3fcaab'},
 'interpretation':['Fresh CPU sampling covers one warmup then three full default compiles at 250us. Fixture loading is excluded; inspector overhead remains (including about 74ms/compile attributed to inspector post). This is not timing-decision evidence. WASM function indices are intentionally unnamed rather than inferred.',
 'History instrumentation preserves every original append. Across 9665 tracked frames, 600761 snapshot calls contain 3165 exact consecutive-per-point repeats (0.5268%). This does not justify a new deduplication path. No such implementation or timing trial follows. Exact track and 147209 charged frames are preserved.'],
 'historyCounts':counts,'studyFiles':files,
 'profiles':{p.name:blob(p) for p in sorted((r/'profile').glob('compile-*.cpuprofile'))},
 'artifacts':{'historyShadow':blob(h/'shadow/scripts/lib/native_motion/engine.wasm')}}
out=repo/'docs/research/engine-after-hypot2-diagnostics-20261104.json';out.write_text(json.dumps(result,indent=2)+'\n');print({'bytes':out.stat().st_size,'files':len(files)})

