const root='/home/holo/line',out=process.argv[2],cwd=out+'/worktree';
snapshotSources(root,cwd,root);symlinkSync(root+'/node_modules',cwd+'/node_modules');
writeFileSync(out+'/protocol.json',JSON.stringify({mode:'compile',warmup:1,reps:3,cells:[61]}));
let source=readFileSync(root+'/tools/parity/parity.ts','utf8');
source="import {Session} from 'node:inspector/promises';\nconst compilerProfiler=new Session(); compilerProfiler.connect(); await compilerProfiler.post('Profiler.enable'); await compilerProfiler.post('Profiler.setSamplingInterval',{interval:250}); let profileCall=0;\n"+source;
source=source.replace('const began = performance.now();',"const began = performance.now();\n  const profiling=++profileCall>1; if(profiling)await compilerProfiler.post('Profiler.start');");
source=source.replace('compileMs: performance.now() - began, track: checkpoint.track}));',`compileMs: performance.now() - began, track: checkpoint.track}));
  if(profiling){const {profile}=await compilerProfiler.post('Profiler.stop');writeFileSync(${JSON.stringify(out)}+'/compile-'+profileCall+'.cpuprofile',JSON.stringify(profile));}`);
writeFileSync(cwd+'/tools/parity/parity.ts',source);writeFileSync(out+'/instrumented-parity.ts',source);
execFileSync(process.execPath,['--expose-gc','--import','tsx','tools/measure/engine_ab.ts','--worker',`--config=${out}/protocol.json`,`--result=${out}/result.json`],{cwd,stdio:'inherit',env:{...process.env,LR_ENGINE:'wasm'}});

